{
  "name": "Kaizen Management System - Master Furnishings Pvt. Ltd.",
  "description": "A professional McKinsey-style Kaizen submission and tracking application for Master Furnishings Pvt. Ltd., featuring department-level analytics, real-time admin review, and performance-based reward tracking."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum KaizenType {
  IDEA = 'Idea',
  IMPLEMENTED = 'Implemented'
}

export enum KaizenStatus {
  PENDING = 'Pending',
  ACCEPTED = 'Accepted',
  REJECTED = 'Rejected'
}

export interface KaizenImpact {
  costSaving: boolean;
  productivity: boolean;
  quality: boolean;
  safety: boolean;
  delivery: boolean;
}

export interface Kaizen {
  id: string;
  department: string;
  initiator: string;
  submissionDate: string;
  presentationDate: string;
  type: KaizenType;
  status: KaizenStatus;
  problem: string;
  solution: string;
  challenges: string;
  impact: KaizenImpact;
  reward: number;
  feedback: string;
  month: string; // e.g., "Jan 26"
  beforeImg?: string;
  afterImg?: string;
}

export interface User {
  id: string;
  name: string;
  role: 'ADMIN' | 'DEPARTMENT';
  department: string;
}

export const DEPARTMENTS = [
  'Chair', 'Furniture', 'CHF', 'Polish', 'RM Store', 'Chair Store', 'FG Store', 
  'Weldshop', 'Logistic', 'Maintenance', 'HSE', 'Admin', 'PPMC'
];

export const MONTHS = [
  'Jan 25', 'Feb 25', 'Mar 25', 'Apr 25', 'May 25', 'Jun 25', 
  'Jul 25', 'Aug 25', 'Sep 25', 'Oct 25', 'Nov 25', 'Dec 25',
  'Jan 26', 'Feb 26', 'Mar 26'
];

import React, { useState, useEffect, useMemo } from 'react';
import { User, Kaizen, KaizenStatus, DEPARTMENTS } from './types';
import Login from './components/Login';
import Dashboard from './components/Dashboard';
import KaizenForm from './components/KaizenForm';
import Records from './components/Records';
import AdminGlobalAnalytics from './components/AdminGlobalAnalytics';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [kaizens, setKaizens] = useState<Kaizen[]>([]);
  const [activeTab, setActiveTab] = useState<'dashboard' | 'submit' | 'records' | 'analytics'>('dashboard');

  // Load initial data from localStorage if available
  useEffect(() => {
    const savedKaizens = localStorage.getItem('kaizen_data');
    if (savedKaizens) {
      setKaizens(JSON.parse(savedKaizens));
    }
  }, []);

  // Save to localStorage on change
  useEffect(() => {
    localStorage.setItem('kaizen_data', JSON.stringify(kaizens));
  }, [kaizens]);

  const handleLogin = (user: User) => {
    setCurrentUser(user);
    setActiveTab('dashboard');
  };

  const handleLogout = () => {
    setCurrentUser(null);
  };

  const addKaizen = (newKaizen: Kaizen) => {
    setKaizens(prev => [newKaizen, ...prev]);
    setActiveTab('records');
  };

  const updateKaizen = (updatedKaizen: Kaizen) => {
    setKaizens(prev => prev.map(k => k.id === updatedKaizen.id ? updatedKaizen : k));
  };

  if (!currentUser) {
    return <Login onLogin={handleLogin} />;
  }

  return (
    <div className="min-h-screen flex flex-col bg-slate-50">
      {/* Top Header */}
      <header className="bg-slate-900 text-white shadow-md py-4 px-6 flex justify-between items-center">
        <div>
          <h1 className="text-xl font-bold tracking-tight">Master Furnishings Pvt. Ltd.</h1>
          <p className="text-xs text-slate-400">Lean Management Portal</p>
        </div>
        <div className="flex items-center gap-6">
          <div className="text-right">
            <p className="text-sm font-medium">{currentUser.department}</p>
            <p className="text-xs text-slate-400 capitalize">{currentUser.role.toLowerCase()}</p>
          </div>
          <button 
            onClick={handleLogout}
            className="px-4 py-2 text-sm bg-slate-800 hover:bg-slate-700 rounded transition-colors"
          >
            Logout
          </button>
        </div>
      </header>

      {/* Navigation */}
      <nav className="bg-white border-b border-slate-200 px-6 py-2 flex gap-4">
        <button 
          onClick={() => setActiveTab('dashboard')}
          className={`px-4 py-2 text-sm font-medium transition-colors border-b-2 ${activeTab === 'dashboard' ? 'border-blue-600 text-blue-600' : 'border-transparent text-slate-500 hover:text-slate-700'}`}
        >
          Dashboard
        </button>
        {currentUser.role === 'DEPARTMENT' && (
          <button 
            onClick={() => setActiveTab('submit')}
            className={`px-4 py-2 text-sm font-medium transition-colors border-b-2 ${activeTab === 'submit' ? 'border-blue-600 text-blue-600' : 'border-transparent text-slate-500 hover:text-slate-700'}`}
          >
            Submit Kaizen
          </button>
        )}
        <button 
          onClick={() => setActiveTab('records')}
          className={`px-4 py-2 text-sm font-medium transition-colors border-b-2 ${activeTab === 'records' ? 'border-blue-600 text-blue-600' : 'border-transparent text-slate-500 hover:text-slate-700'}`}
        >
          {currentUser.role === 'ADMIN' ? 'Global Records' : 'My Records'}
        </button>
        {currentUser.role === 'ADMIN' && (
          <button 
            onClick={() => setActiveTab('analytics')}
            className={`px-4 py-2 text-sm font-medium transition-colors border-b-2 ${activeTab === 'analytics' ? 'border-blue-600 text-blue-600' : 'border-transparent text-slate-500 hover:text-slate-700'}`}
          >
            Global Analytics
          </button>
        )}
      </nav>

      {/* Main Content */}
      <main className="flex-1 overflow-auto p-6 pb-20">
        <div className="max-w-7xl mx-auto">
          {activeTab === 'dashboard' && (
            <Dashboard user={currentUser} kaizens={kaizens} />
          )}
          {activeTab === 'submit' && currentUser.role === 'DEPARTMENT' && (
            <KaizenForm department={currentUser.department} onSubmit={addKaizen} />
          )}
          {activeTab === 'records' && (
            <Records 
              user={currentUser} 
              kaizens={kaizens} 
              onUpdate={updateKaizen}
            />
          )}
          {activeTab === 'analytics' && currentUser.role === 'ADMIN' && (
            <AdminGlobalAnalytics kaizens={kaizens} />
          )}
        </div>
      </main>

      {/* Footer / Watermark */}
      <footer className="bg-white border-t border-slate-200 py-3 px-6 text-center text-xs text-slate-400 sticky bottom-0 z-10">
        <div className="flex justify-between items-center max-w-7xl mx-auto">
          <p>© 2025 Master Furnishings Pvt. Ltd. | Kaizen Optimization System</p>
          <p className="italic font-medium text-slate-500 opacity-50 select-none">Develop by Hamza Raza</p>
        </div>
      </footer>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { User, DEPARTMENTS } from '../types';

interface LoginProps {
  onLogin: (user: User) => void;
}

const Login: React.FC<LoginProps> = ({ onLogin }) => {
  const [id, setId] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    // Admin Login Logic
    if (id.toLowerCase() === 'admin' && password === 'Lean2025') {
      onLogin({ id: 'admin', name: 'Lean Admin', role: 'ADMIN', department: 'Lean Department' });
      return;
    }

    // Department Login Logic (ID = Dept Name lowercased, Pass = 123 for demo)
    const normalizedId = id.trim().toLowerCase();
    const dept = DEPARTMENTS.find(d => d.toLowerCase() === normalizedId);

    if (dept && password === '123') {
      onLogin({ id: dept.toLowerCase(), name: dept, role: 'DEPARTMENT', department: dept });
      return;
    }

    setError('Invalid ID or Password. (Hint: Use dept name and "123", or "admin" and "Lean2025")');
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-slate-900 p-4">
      <div className="w-full max-w-md bg-white rounded-xl shadow-2xl overflow-hidden">
        <div className="bg-slate-800 p-8 text-white text-center">
          <h2 className="text-2xl font-bold">Master Furnishings Pvt. Ltd.</h2>
          <p className="text-slate-400 mt-2">Kaizen Submission Portal</p>
        </div>
        <form onSubmit={handleSubmit} className="p-8 space-y-6">
          {error && (
            <div className="bg-red-50 text-red-600 p-3 rounded text-sm border border-red-100">
              {error}
            </div>
          )}
          <div>
            <label className="block text-sm font-semibold text-slate-700 mb-2">User ID (Department Name)</label>
            <input 
              type="text" 
              value={id}
              onChange={(e) => setId(e.target.value)}
              className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-lg focus:ring-2 focus:ring-blue-500 focus:outline-none transition-all"
              placeholder="e.g. Chair, Admin, Weldshop"
              required
            />
          </div>
          <div>
            <label className="block text-sm font-semibold text-slate-700 mb-2">Password</label>
            <input 
              type="password" 
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-lg focus:ring-2 focus:ring-blue-500 focus:outline-none transition-all"
              placeholder="••••••••"
              required
            />
          </div>
          <button 
            type="submit"
            className="w-full bg-slate-900 hover:bg-slate-800 text-white font-bold py-3 rounded-lg transition-all shadow-lg active:scale-[0.98]"
          >
            Sign In
          </button>
          <div className="text-center">
            <p className="text-xs text-slate-500">
              Internal use only. Unauthorized access is prohibited.
            </p>
          </div>
        </form>
      </div>
    </div>
  );
};

export default Login;

import React, { useMemo, useState } from 'react';
import { User, Kaizen, KaizenStatus, KaizenType, MONTHS, DEPARTMENTS } from '../types';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer, LineChart, Line } from 'recharts';

interface DashboardProps {
  user: User;
  kaizens: Kaizen[];
}

const Dashboard: React.FC<DashboardProps> = ({ user, kaizens }) => {
  const [selectedMonth, setSelectedMonth] = useState<string>('All');
  const [selectedDept, setSelectedDept] = useState<string>(user.role === 'ADMIN' ? 'All' : user.department);

  // Filter kaizens based on selection
  const filteredKaizens = useMemo(() => {
    return kaizens.filter(k => {
      const monthMatch = selectedMonth === 'All' || k.month === selectedMonth;
      const deptMatch = selectedDept === 'All' || k.department === selectedDept;
      return monthMatch && deptMatch;
    });
  }, [kaizens, selectedMonth, selectedDept]);

  // Derived metrics
  const stats = useMemo(() => {
    const total = filteredKaizens.length;
    const acceptedIdeas = filteredKaizens.filter(k => k.status === KaizenStatus.ACCEPTED && k.type === KaizenType.IDEA).length;
    const acceptedImp = filteredKaizens.filter(k => k.status === KaizenStatus.ACCEPTED && k.type === KaizenType.IMPLEMENTED).length;
    const rejectedIdeas = filteredKaizens.filter(k => k.status === KaizenStatus.REJECTED && k.type === KaizenType.IDEA).length;
    const rejectedImp = filteredKaizens.filter(k => k.status === KaizenStatus.REJECTED && k.type === KaizenType.IMPLEMENTED).length;
    const pending = filteredKaizens.filter(k => k.status === KaizenStatus.PENDING).length;
    const totalReward = (acceptedIdeas * 50) + (acceptedImp * 200);

    const ideaCount = filteredKaizens.filter(k => k.type === KaizenType.IDEA).length;
    const impCount = filteredKaizens.filter(k => k.type === KaizenType.IMPLEMENTED).length;

    // Participation Calculation
    // Target is 4 per department per month.
    let activeDepts = selectedDept === 'All' ? DEPARTMENTS.length : 1;
    let monthsIncluded = 1;
    if (selectedMonth === 'All') {
      const uniqueMonthsInRecords = Array.from(new Set(kaizens.map(k => k.month)));
      monthsIncluded = Math.max(1, uniqueMonthsInRecords.length);
    }

    const target = activeDepts * monthsIncluded * 4;
    const participationRate = target > 0 ? (total / target) * 100 : 0;

    return { 
      total, 
      acceptedIdeas, 
      acceptedImp, 
      rejectedIdeas, 
      rejectedImp, 
      pending,
      totalReward, 
      participationRate,
      target,
      ideaCount,
      impCount
    };
  }, [filteredKaizens, selectedMonth, selectedDept, kaizens]);

  // Chart Data: Department-wise Participation
  const chartData = useMemo(() => {
    return DEPARTMENTS.map(dept => {
      const deptKaizens = filteredKaizens.filter(k => k.department === dept);
      return {
        name: dept,
        submissions: deptKaizens.length,
        target: stats.target / (selectedDept === 'All' ? DEPARTMENTS.length : 1), // target per dept
      };
    }).filter(d => d.submissions > 0 || selectedDept === 'All');
  }, [filteredKaizens, selectedDept, stats.target]);

  // Comparison Data: Last Month vs Current
  const comparisonData = useMemo(() => {
    if (selectedMonth === 'All') return [];

    // Simple logic to find previous month from MONTHS constant
    const currentIndex = MONTHS.indexOf(selectedMonth);
    const prevMonth = currentIndex > 0 ? MONTHS[currentIndex - 1] : null;

    const currentCount = kaizens.filter(k => k.month === selectedMonth && (selectedDept === 'All' || k.department === selectedDept)).length;
    const prevCount = prevMonth ? kaizens.filter(k => k.month === prevMonth && (selectedDept === 'All' || k.department === selectedDept)).length : 0;

    return [
      { month: prevMonth || 'N/A', count: prevCount },
      { month: selectedMonth, count: currentCount }
    ];
  }, [selectedMonth, kaizens, selectedDept]);

  return (
    <div className="space-y-6">
      {/* Filters */}
      <div className="flex flex-wrap gap-4 items-center justify-between bg-white p-4 rounded-lg shadow-sm border border-slate-100">
        <h2 className="text-lg font-bold text-slate-800">
          {user.role === 'ADMIN' ? 'Global Analytics' : `Dashboard: ${user.department}`}
        </h2>
        <div className="flex gap-4">
          <select 
            value={selectedMonth} 
            onChange={(e) => setSelectedMonth(e.target.value)}
            className="px-3 py-2 border border-slate-200 rounded text-sm focus:ring-2 focus:ring-blue-500 outline-none"
          >
            <option value="All">All Months</option>
            {MONTHS.map(m => <option key={m} value={m}>{m}</option>)}
          </select>
          {user.role === 'ADMIN' && (
            <select 
              value={selectedDept} 
              onChange={(e) => setSelectedDept(e.target.value)}
              className="px-3 py-2 border border-slate-200 rounded text-sm focus:ring-2 focus:ring-blue-500 outline-none"
            >
              <option value="All">All Departments</option>
              {DEPARTMENTS.map(d => <option key={d} value={d}>{d}</option>)}
            </select>
          )}
        </div>
      </div>

      {/* Metric Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        <div className="bg-white p-6 rounded-lg shadow-sm border border-slate-100">
          <p className="text-sm font-medium text-slate-500 uppercase">Total Kaizen Received</p>
          <p className="text-3xl font-bold text-slate-900 mt-1">{stats.total}</p>
          <div className="mt-2 text-xs text-slate-400 space-y-1">
            <p>Ideas: {stats.ideaCount}</p>
            <p>Implemented: {stats.impCount}</p>
          </div>
        </div>
        <div className="bg-white p-6 rounded-lg shadow-sm border border-slate-100">
          <p className="text-sm font-medium text-slate-500 uppercase">Participation Rate</p>
          <p className="text-3xl font-bold text-blue-600 mt-1">{stats.participationRate.toFixed(1)}%</p>
          <p className="text-xs text-slate-400 mt-2">Target: {stats.target} ({stats.total}/{stats.target})</p>
        </div>
        <div className="bg-white p-6 rounded-lg shadow-sm border border-slate-100">
          <p className="text-sm font-medium text-slate-500 uppercase">Accepted Rewards</p>
          <p className="text-3xl font-bold text-emerald-600 mt-1">{stats.totalReward.toLocaleString()} <span className="text-sm font-normal">PKR</span></p>
          <p className="text-xs text-slate-400 mt-2">Idea: {stats.acceptedIdeas} | Imp: {stats.acceptedImp}</p>
        </div>
        <div className="bg-white p-6 rounded-lg shadow-sm border border-slate-100 border-l-4 border-l-amber-400">
          <p className="text-sm font-medium text-slate-500 uppercase">Pending Review</p>
          <p className="text-3xl font-bold text-amber-500 mt-1">{stats.pending}</p>
          <p className="text-xs text-slate-400 mt-2">Needs Admin Approval</p>
        </div>
      </div>

      {/* Breakdown Summary */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        <div className="bg-white p-6 rounded-lg shadow-sm border border-slate-100">
          <h3 className="text-md font-bold text-slate-800 mb-4 border-b pb-2">Status Breakdown</h3>
          <div className="space-y-3">
            <div className="flex justify-between items-center p-2 bg-emerald-50 rounded">
              <span className="text-sm font-medium text-emerald-800">Accepted Ideas</span>
              <span className="font-bold text-emerald-600">{stats.acceptedIdeas}</span>
            </div>
            <div className="flex justify-between items-center p-2 bg-emerald-100 rounded">
              <span className="text-sm font-medium text-emerald-900">Accepted Implemented</span>
              <span className="font-bold text-emerald-700">{stats.acceptedImp}</span>
            </div>
            <div className="flex justify-between items-center p-2 bg-red-50 rounded">
              <span className="text-sm font-medium text-red-800">Rejected Ideas</span>
              <span className="font-bold text-red-600">{stats.rejectedIdeas}</span>
            </div>
            <div className="flex justify-between items-center p-2 bg-red-100 rounded">
              <span className="text-sm font-medium text-red-900">Rejected Implemented</span>
              <span className="font-bold text-red-700">{stats.rejectedImp}</span>
            </div>
          </div>
        </div>

        <div className="bg-white p-6 rounded-lg shadow-sm border border-slate-100">
          <h3 className="text-md font-bold text-slate-800 mb-4 border-b pb-2">Financial Summary</h3>
          <div className="space-y-4">
            <div className="flex justify-between">
              <span className="text-slate-500 text-sm">Idea Reward (50/each):</span>
              <span className="font-semibold">{stats.acceptedIdeas * 50} PKR</span>
            </div>
            <div className="flex justify-between">
              <span className="text-slate-500 text-sm">Implemented Reward (200/each):</span>
              <span className="font-semibold">{stats.acceptedImp * 200} PKR</span>
            </div>
            <div className="border-t pt-2 flex justify-between">
              <span className="font-bold text-slate-800">Total Rewards Due:</span>
              <span className="font-bold text-blue-600">{stats.totalReward} PKR</span>
            </div>
          </div>
        </div>
      </div>

      {/* Charts Section */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Participation Chart */}
        <div className="bg-white p-6 rounded-lg shadow-sm border border-slate-100">
          <h3 className="text-md font-bold text-slate-800 mb-4">Department-wise Participation</h3>
          <div className="h-64">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={chartData}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} />
                <XAxis dataKey="name" fontSize={10} angle={-45} textAnchor="end" height={60} />
                <YAxis />
                <Tooltip />
                <Legend />
                <Bar dataKey="submissions" name="Actual Submissions" fill="#1e293b" radius={[4, 4, 0, 0]} />
                <Bar dataKey="target" name="Monthly Target" fill="#94a3b8" opacity={0.3} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Growth Chart */}
        <div className="bg-white p-6 rounded-lg shadow-sm border border-slate-100">
          <h3 className="text-md font-bold text-slate-800 mb-4">Month-over-Month Comparison</h3>
          {comparisonData.length > 0 ? (
            <div className="h-64">
              <ResponsiveContainer width="100%" height="100%">
                <LineChart data={comparisonData}>
                  <CartesianGrid strokeDasharray="3 3" vertical={false} />
                  <XAxis dataKey="month" />
                  <YAxis />
                  <Tooltip />
                  <Line type="monotone" dataKey="count" name="Submissions" stroke="#2563eb" strokeWidth={3} dot={{ r: 6 }} />
                </LineChart>
              </ResponsiveContainer>
            </div>
          ) : (
            <div className="h-64 flex items-center justify-center text-slate-400">
              Select a specific month to see comparison
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState } from 'react';
import { Kaizen, KaizenType, KaizenStatus, MONTHS } from '../types';

interface KaizenFormProps {
  department: string;
  onSubmit: (kaizen: Kaizen) => void;
}

const KaizenForm: React.FC<KaizenFormProps> = ({ department, onSubmit }) => {
  const [formData, setFormData] = useState({
    initiator: '',
    presentationDate: new Date().toISOString().split('T')[0],
    type: KaizenType.IDEA,
    month: MONTHS[0],
    problem: '',
    solution: '',
    challenges: '',
    impact: {
      costSaving: false,
      productivity: false,
      quality: false,
      safety: false,
      delivery: false
    }
  });

  const [images, setImages] = useState({ before: '', after: '' });

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>, type: 'before' | 'after') => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setImages(prev => ({ ...prev, [type]: reader.result as string }));
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const newKaizen: Kaizen = {
      ...formData,
      id: Math.random().toString(36).substr(2, 9),
      department,
      submissionDate: new Date().toLocaleDateString(),
      status: KaizenStatus.PENDING,
      reward: 0,
      feedback: '',
      beforeImg: images.before,
      afterImg: images.after
    };
    onSubmit(newKaizen);
  };

  return (
    <div className="bg-white rounded-xl shadow-lg border border-slate-200 overflow-hidden max-w-4xl mx-auto">
      <div className="bg-slate-900 p-6 text-white">
        <h2 className="text-2xl font-bold">New Kaizen Submission</h2>
        <p className="text-slate-400">Department: {department}</p>
      </div>

      <form onSubmit={handleSubmit} className="p-8 space-y-8">
        {/* Basic Info */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div>
            <label className="block text-sm font-semibold text-slate-700 mb-2">Initiator Name</label>
            <input 
              type="text" 
              required
              value={formData.initiator}
              onChange={e => setFormData({...formData, initiator: e.target.value})}
              className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none"
              placeholder="Who started this Kaizen?"
            />
          </div>
          <div>
            <label className="block text-sm font-semibold text-slate-700 mb-2">Presentation Date</label>
            <input 
              type="date" 
              required
              value={formData.presentationDate}
              onChange={e => setFormData({...formData, presentationDate: e.target.value})}
