import React, { useMemo, useState } from 'react';
import { Kaizen, KaizenStatus, KaizenType, DEPARTMENTS, MONTHS } from '../types';

interface AdminGlobalAnalyticsProps {
  kaizens: Kaizen[];
}

const AdminGlobalAnalytics: React.FC<AdminGlobalAnalyticsProps> = ({ kaizens }) => {
  const [selectedMonth, setSelectedMonth] = useState<string>('All');

  const analytics = useMemo(() => {
    return DEPARTMENTS.map(dept => {
      const deptKaizens = kaizens.filter(k => 
        (selectedMonth === 'All' || k.month === selectedMonth) && 
        k.department === dept
      );

      // Month calculation for target
      let monthsCount = 1;
      if (selectedMonth === 'All') {
        monthsCount = Math.max(1, Array.from(new Set(kaizens.map(k => k.month))).length);
      }
      const target = monthsCount * 4;

      const accIdeas = deptKaizens.filter(k => k.status === KaizenStatus.ACCEPTED && k.type === KaizenType.IDEA).length;
      const accImp = deptKaizens.filter(k => k.status === KaizenStatus.ACCEPTED && k.type === KaizenType.IMPLEMENTED).length;
      const rejIdeas = deptKaizens.filter(k => k.status === KaizenStatus.REJECTED && k.type === KaizenType.IDEA).length;
      const rejImp = deptKaizens.filter(k => k.status === KaizenStatus.REJECTED && k.type === KaizenType.IMPLEMENTED).length;
      const pending = deptKaizens.filter(k => k.status === KaizenStatus.PENDING).length;

      const participation = target > 0 ? (deptKaizens.length / target) * 100 : 0;
      const totalReward = (accIdeas * 50) + (accImp * 200);

      return {
        dept,
        total: deptKaizens.length,
        accIdeas,
        accImp,
        rejIdeas,
        rejImp,
        pending,
        participation,
        totalReward,
        target
      };
    }).sort((a, b) => b.participation - a.participation);
  }, [kaizens, selectedMonth]);

  const totals = useMemo(() => {
    return analytics.reduce((acc, curr) => ({
      total: acc.total + curr.total,
      accIdeas: acc.accIdeas + curr.accIdeas,
      accImp: acc.accImp + curr.accImp,
      rejIdeas: acc.rejIdeas + curr.rejIdeas,
      rejImp: acc.rejImp + curr.rejImp,
      reward: acc.reward + curr.totalReward
    }), { total: 0, accIdeas: 0, accImp: 0, rejIdeas: 0, rejImp: 0, reward: 0 });
  }, [analytics]);

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center bg-white p-4 rounded-lg shadow-sm border border-slate-100">
        <h2 className="text-xl font-bold text-slate-800 tracking-tight">Department-wise League Table</h2>
        <select 
          value={selectedMonth} 
          onChange={(e) => setSelectedMonth(e.target.value)}
          className="px-4 py-2 border border-slate-200 rounded-lg text-sm font-medium focus:ring-2 focus:ring-blue-500 outline-none"
        >
          <option value="All">Cumulative Analytics</option>
          {MONTHS.map(m => <option key={m} value={m}>{m}</option>)}
        </select>
      </div>

      <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse">
            <thead>
              <tr className="bg-slate-900 text-white uppercase text-[10px] tracking-widest font-bold">
                <th className="px-4 py-4 border-r border-slate-700">Department</th>
                <th className="px-4 py-4 border-r border-slate-700 text-center">Participation %</th>
                <th className="px-4 py-4 border-r border-slate-700 text-center">Total Rec.</th>
                <th className="px-4 py-4 border-r border-slate-700 text-center">Acc. Idea</th>
                <th className="px-4 py-4 border-r border-slate-700 text-center">Acc. Imp.</th>
                <th className="px-4 py-4 border-r border-slate-700 text-center text-red-400">Rej. Idea</th>
                <th className="px-4 py-4 border-r border-slate-700 text-center text-red-400">Rej. Imp.</th>
                <th className="px-4 py-4 border-r border-slate-700 text-center text-amber-400">Pending</th>
                <th className="px-4 py-4 text-right">Total Reward (PKR)</th>
              </tr>
            </thead>
            <tbody className="text-sm divide-y divide-slate-100">
              {analytics.map(row => (
                <tr key={row.dept} className="hover:bg-slate-50 transition-colors">
                  <td className="px-4 py-4 border-r border-slate-100 font-bold text-slate-800">{row.dept}</td>
                  <td className="px-4 py-4 border-r border-slate-100 text-center">
                    <div className="flex items-center gap-2 justify-center">
                      <div className="w-16 bg-slate-100 rounded-full h-2 overflow-hidden">
                        <div 
                          className={`h-full ${row.participation >= 100 ? 'bg-emerald-500' : 'bg-blue-600'}`} 
                          style={{ width: `${Math.min(100, row.participation)}%` }} 
                        />
                      </div>
                      <span className="font-bold min-w-[3rem]">{row.participation.toFixed(1)}%</span>
                    </div>
                  </td>
                  <td className="px-4 py-4 border-r border-slate-100 text-center font-medium">{row.total} / {row.target}</td>
                  <td className="px-4 py-4 border-r border-slate-100 text-center text-emerald-600 font-bold">{row.accIdeas}</td>
                  <td className="px-4 py-4 border-r border-slate-100 text-center text-emerald-700 font-bold">{row.accImp}</td>
                  <td className="px-4 py-4 border-r border-slate-100 text-center text-red-500">{row.rejIdeas}</td>
                  <td className="px-4 py-4 border-r border-slate-100 text-center text-red-500">{row.rejImp}</td>
                  <td className="px-4 py-4 border-r border-slate-100 text-center text-amber-600 font-bold">{row.pending}</td>
                  <td className="px-4 py-4 text-right font-bold text-slate-900">{row.totalReward.toLocaleString()}</td>
                </tr>
              ))}
            </tbody>
            <tfoot className="bg-slate-50 border-t-2 border-slate-200">
              <tr className="font-bold text-slate-900">
                <td className="px-4 py-4 border-r border-slate-200">GRAND TOTAL</td>
                <td className="px-4 py-4 border-r border-slate-200"></td>
                <td className="px-4 py-4 border-r border-slate-200 text-center">{totals.total}</td>
                <td className="px-4 py-4 border-r border-slate-200 text-center">{totals.accIdeas}</td>
                <td className="px-4 py-4 border-r border-slate-200 text-center">{totals.accImp}</td>
                <td className="px-4 py-4 border-r border-slate-200 text-center">{totals.rejIdeas}</td>
                <td className="px-4 py-4 border-r border-slate-200 text-center">{totals.rejImp}</td>
                <td className="px-4 py-4 border-r border-slate-200 text-center"></td>
                <td className="px-4 py-4 text-right text-blue-700 text-lg">{totals.reward.toLocaleString()} PKR</td>
              </tr>
            </tfoot>
          </table>
        </div>
      </div>

      <div className="bg-amber-50 border-l-4 border-amber-400 p-4 rounded text-amber-800 text-sm">
        <strong>Note for Finance:</strong> The total reward of <strong>{totals.reward.toLocaleString()} PKR</strong> represents all accepted Kaizens for the selected period.
      </div>
    </div>
  );
};

