  const filtered = useMemo(() => {
    return kaizens.filter(k => {
      const mMatch = monthFilter === 'All' || k.month === monthFilter;
      const sMatch = statusFilter === 'All' || k.status === statusFilter;
      const dMatch = deptFilter === 'All' || k.department === deptFilter;
      return mMatch && sMatch && dMatch;
    });
  }, [kaizens, monthFilter, statusFilter, deptFilter]);

  const handleReview = (status: KaizenStatus) => {
    if (!selectedKaizen) return;
    let reward = 0;
    if (status === KaizenStatus.ACCEPTED) {
      reward = selectedKaizen.type === KaizenType.IDEA ? 50 : 200;
    }

    onUpdate({
      ...selectedKaizen,
      status,
      reward,
      feedback: (document.getElementById('feedback-input') as HTMLTextAreaElement)?.value || selectedKaizen.feedback
    });
    setSelectedKaizen(null);
  };

  return (
    <div className="space-y-6">
      {/* Search & Filters */}
      <div className="bg-white p-4 rounded-lg shadow-sm border border-slate-200 flex flex-wrap gap-4 items-end">
        <div>
          <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Month</label>
          <select 
            value={monthFilter} 
            onChange={e => setMonthFilter(e.target.value)}
            className="px-3 py-2 border border-slate-200 rounded text-sm focus:ring-2 focus:ring-blue-500 outline-none"
          >
            <option value="All">All Active Months</option>
            {activeMonths.map(m => <option key={m} value={m}>{m}</option>)}
          </select>
        </div>
        <div>
          <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Status</label>
          <select 
            value={statusFilter} 
            onChange={e => setStatusFilter(e.target.value)}
            className="px-3 py-2 border border-slate-200 rounded text-sm focus:ring-2 focus:ring-blue-500 outline-none"
          >
            <option value="All">All Statuses</option>
            <option value={KaizenStatus.PENDING}>Pending</option>
            <option value={KaizenStatus.ACCEPTED}>Accepted</option>
            <option value={KaizenStatus.REJECTED}>Rejected</option>
          </select>
        </div>
        {user.role === 'ADMIN' && (
          <div>
            <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Department</label>
            <select 
              value={deptFilter} 
              onChange={e => setDeptFilter(e.target.value)}
              className="px-3 py-2 border border-slate-200 rounded text-sm focus:ring-2 focus:ring-blue-500 outline-none"
            >
              <option value="All">All Departments</option>
              {DEPARTMENTS.map(d => <option key={d} value={d}>{d}</option>)}
            </select>
          </div>
        )}
        <div className="ml-auto text-sm text-slate-500 font-medium italic">
          Showing {filtered.length} records
        </div>
      </div>

      {/* Table */}
      <div className="bg-white rounded-lg shadow-sm border border-slate-200 overflow-hidden">
        <table className="w-full text-left">
          <thead className="bg-slate-50 border-b border-slate-200">
            <tr>
              <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase">Date</th>
              {user.role === 'ADMIN' && <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase">Dept</th>}
              <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase">Initiator</th>
              <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase">Type</th>
              <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase">Status</th>
              <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase text-right">Reward</th>
              <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase text-center">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {filtered.map(k => (
              <tr key={k.id} className="hover:bg-slate-50 transition-colors">
                <td className="px-6 py-4 text-sm text-slate-700">{k.submissionDate}</td>
                {user.role === 'ADMIN' && <td className="px-6 py-4 text-sm font-semibold text-slate-900">{k.department}</td>}
                <td className="px-6 py-4 text-sm font-medium text-blue-600">{k.initiator}</td>
                <td className="px-6 py-4 text-sm text-slate-600">{k.type}</td>
                <td className="px-6 py-4">
                  <span className={`px-2 py-1 rounded-full text-[10px] font-bold uppercase ${
                    k.status === KaizenStatus.ACCEPTED ? 'bg-emerald-100 text-emerald-700' :
                    k.status === KaizenStatus.REJECTED ? 'bg-red-100 text-red-700' : 'bg-amber-100 text-amber-700'
                  }`}>
                    {k.status}
                  </span>
                </td>
                <td className="px-6 py-4 text-sm text-slate-900 text-right font-bold">{k.reward} PKR</td>
                <td className="px-6 py-4 text-center">
                  <button 
                    onClick={() => setSelectedKaizen(k)}
                    className="text-blue-600 hover:text-blue-800 text-xs font-bold"
                  >
                    View Details
                  </button>
                </td>
              </tr>
            ))}
            {filtered.length === 0 && (
              <tr>
                <td colSpan={7} className="px-6 py-12 text-center text-slate-400 italic">No records found matching filters.</td>
              </tr>
            )}
          </tbody>
        </table>
      </div>

      {/* Detail Modal */}
      {selectedKaizen && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm flex items-center justify-center p-4 z-50">
          <div className="bg-white rounded-xl shadow-2xl max-w-4xl w-full max-h-[90vh] overflow-y-auto">
            <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-900 text-white rounded-t-xl">
              <div>
                <h3 className="text-xl font-bold">{selectedKaizen.type}: {selectedKaizen.initiator}</h3>
                <p className="text-sm opacity-70">Submitted {selectedKaizen.submissionDate} | {selectedKaizen.month}</p>
              </div>
              <button onClick={() => setSelectedKaizen(null)} className="text-white hover:opacity-70 text-2xl">×</button>
            </div>

            <div className="p-8 space-y-8">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                <div>
                  <h4 className="text-xs font-bold text-slate-400 uppercase mb-2">Problem</h4>
                  <p className="text-slate-800 text-sm leading-relaxed whitespace-pre-wrap">{selectedKaizen.problem}</p>
                </div>
                <div>
                  <h4 className="text-xs font-bold text-slate-400 uppercase mb-2">Solution</h4>
                  <p className="text-slate-800 text-sm leading-relaxed whitespace-pre-wrap">{selectedKaizen.solution}</p>
                </div>
              </div>

              <div>
                <h4 className="text-xs font-bold text-slate-400 uppercase mb-3">Impact Matrix</h4>
                <div className="flex flex-wrap gap-2">
                  {Object.entries(selectedKaizen.impact).map(([key, value]) => (
                    <span key={key} className={`px-3 py-1 rounded text-xs font-bold border ${value ? 'bg-blue-50 border-blue-200 text-slate-600' : 'bg-slate-50 border-slate-100 text-slate-300'}`}>
                      {key.replace('Saving', ' Saving').toUpperCase()}
                    </span>
                  ))}
                </div>
              </div>

              {(selectedKaizen.beforeImg || selectedKaizen.afterImg) && (
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  {selectedKaizen.beforeImg && (
                    <div>
                      <h4 className="text-xs font-bold text-slate-400 uppercase mb-2 text-center">Before</h4>
                      <img src={selectedKaizen.beforeImg} className="w-full h-64 object-cover rounded-lg border shadow-inner" alt="Before" />
                    </div>
                  )}
                  {selectedKaizen.afterImg && (
                    <div>
                      <h4 className="text-xs font-bold text-slate-400 uppercase mb-2 text-center">After</h4>
                      <img src={selectedKaizen.afterImg} className="w-full h-64 object-cover rounded-lg border shadow-inner" alt="After" />
                    </div>
                  )}
                </div>
              )}

              {/* Admin Review Section */}
              {user.role === 'ADMIN' && selectedKaizen.status === KaizenStatus.PENDING && (
                <div className="bg-slate-50 p-6 rounded-xl border border-slate-200 space-y-4">
                  <h4 className="text-sm font-bold text-slate-800 uppercase tracking-wide">Review Section</h4>
                  <textarea 
                    id="feedback-input"
                    className="w-full p-4 border border-slate-200 rounded-lg h-24 text-sm focus:ring-2 focus:ring-blue-500 outline-none"
                    placeholder="Provide feedback for improvement or reasons for rejection..."
                    defaultValue={selectedKaizen.feedback}
                  />
                  <div className="flex gap-4">
                    <button 
                      onClick={() => handleReview(KaizenStatus.ACCEPTED)}
                      className="flex-1 bg-emerald-600 hover:bg-emerald-700 text-white font-bold py-3 rounded-lg shadow transition-all"
                    >
                      Accept Kaizen
                    </button>
                    <button 
                      onClick={() => handleReview(KaizenStatus.REJECTED)}
                      className="flex-1 bg-red-600 hover:bg-red-700 text-white font-bold py-3 rounded-lg shadow transition-all"
                    >
                      Reject Kaizen
                    </button>
                  </div>
                </div>
              )}

              {/* Status & Feedback Display */}
              {selectedKaizen.status !== KaizenStatus.PENDING && (
                <div className={`p-6 rounded-xl border ${selectedKaizen.status === KaizenStatus.ACCEPTED ? 'bg-emerald-50 border-emerald-100' : 'bg-red-50 border-red-100'}`}>
                  <h4 className="text-sm font-bold uppercase tracking-wide mb-2">Review Summary</h4>
                  <p className="text-sm font-semibold mb-2">Status: {selectedKaizen.status} | Reward: {selectedKaizen.reward} PKR</p>
                  {selectedKaizen.feedback && (
                    <div className="mt-3 text-sm italic text-slate-600">
                      " {selectedKaizen.feedback} "
                    </div>
                  )}
                </div>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

