            <p className="text-sm font-bold text-blue-400 uppercase">{currentUser.department}</p>
            <p className="text-[10px] text-slate-400 uppercase tracking-widest">{currentUser.role}</p>
          </div>
          <button 
            onClick={handleLogout}
            className="px-4 py-1.5 text-xs font-bold border border-slate-600 hover:bg-slate-800 rounded transition-all uppercase"
          >
            Logout
          </button>
        </div>
      </header>

      <nav className="bg-white border-b border-slate-200 px-6 py-1 flex gap-2">
        <button 
          onClick={() => setActiveTab('dashboard')}
          className={`px-4 py-3 text-xs font-bold uppercase transition-all border-b-2 ${activeTab === 'dashboard' ? 'border-blue-600 text-blue-600' : 'border-transparent text-slate-500 hover:text-slate-800'}`}
        >
          Dashboard
        </button>
        {currentUser.role === 'DEPARTMENT' && (
          <button 
            onClick={() => setActiveTab('submit')}
