            Submit Kaizen
          </button>
        )}
        <button 
          onClick={() => setActiveTab('records')}
          className={`px-4 py-3 text-xs font-bold uppercase transition-all border-b-2 ${activeTab === 'records' ? 'border-blue-600 text-blue-600' : 'border-transparent text-slate-500 hover:text-slate-800'}`}
        >
          Records Management
        </button>
        {currentUser.role === 'ADMIN' && (
          <button 
            onClick={() => setActiveTab('analytics')}
            className={`px-4 py-3 text-xs font-bold uppercase transition-all border-b-2 ${activeTab === 'analytics' ? 'border-blue-600 text-blue-600' : 'border-transparent text-slate-500 hover:text-slate-800'}`}
          >
            Global Analytics
          </button>
        )}
      </nav>

      <main className="flex-1 overflow-auto p-6 pb-24">
        <div className="max-w-7xl mx-auto">
          {/* Key ensures components reset state when switching users */}
          {activeTab === 'dashboard' && (
            <Dashboard key={currentUser.id} user={currentUser} kaizens={kaizens} />
          )}
          {activeTab === 'submit' && currentUser.role === 'DEPARTMENT' && (
            <KaizenForm department={currentUser.department} onSubmit={addKaizen} />
