            <span className="h-1 w-1 bg-slate-300 rounded-full"></span>
            <p className="italic font-bold text-slate-500 uppercase tracking-widest opacity-60">Develop by Hamza Raza</p>
          </div>
        </div>
      </footer>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
