            />
          </div>
          <div>
            <label className="block text-[10px] font-bold text-slate-500 uppercase mb-2 tracking-widest">Access Password</label>
            <input 
              type="password" 
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded text-sm focus:border-blue-500 focus:ring-0 outline-none transition-all placeholder:text-slate-300"
              placeholder="••••••••"
              required
            />
          </div>
          <button 
            type="submit"
            className="w-full bg-slate-900 hover:bg-black text-white text-xs font-bold uppercase py-4 rounded transition-all shadow-xl active:scale-[0.98]"
          >
            Authenticate User
          </button>
          <div className="pt-4 text-center">
            <p className="text-[10px] text-slate-400 leading-relaxed uppercase">
              Authorized Personnel Only. Logins are Monitored.
              <br/>
              <span className="font-bold text-slate-500">Hint: Admin/Lean2025 or DeptName/123</span>
            </p>
          </div>
        </form>
      </div>
    </div>
  );
};

