import React, { useState, useEffect } from 'react';
import { User, Kaizen, DEPARTMENTS } from './types';
import Login from './components/Login';
import Dashboard from './components/Dashboard';
import KaizenForm from './components/KaizenForm';
import Records from './components/Records';
import AdminGlobalAnalytics from './components/AdminGlobalAnalytics';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [kaizens, setKaizens] = useState<Kaizen[]>([]);
  const [activeTab, setActiveTab] = useState<'dashboard' | 'submit' | 'records' | 'analytics'>('dashboard');

  useEffect(() => {
    try {
      const savedKaizens = localStorage.getItem('kaizen_data');
      if (savedKaizens) {
        setKaizens(JSON.parse(savedKaizens));
      }
    } catch (e) {
      console.error("Failed to load Kaizen data", e);
    }
  }, []);

  useEffect(() => {
    try {
      if (kaizens.length > 0) {
        localStorage.setItem('kaizen_data', JSON.stringify(kaizens));
      }
    } catch (e) {
      console.error("Storage limit reached or failed to save", e);
      alert("Warning: Local storage limit reached. Large images might not be saved.");
    }
  }, [kaizens]);

  const handleLogin = (user: User) => {
    setCurrentUser(user);
    setActiveTab('dashboard');
  };

  const handleLogout = () => {
    setCurrentUser(null);
  };

  const addKaizen = (newKaizen: Kaizen) => {
    setKaizens(prev => [newKaizen, ...prev]);
    // Small delay to allow state to settle before switching tabs
    setTimeout(() => {
      setActiveTab('records');
    }, 100);
  };

  const updateKaizen = (updatedKaizen: Kaizen) => {
    setKaizens(prev => prev.map(k => k.id === updatedKaizen.id ? updatedKaizen : k));
  };

  if (!currentUser) {
    return <Login onLogin={handleLogin} />;
  }

  return (
    <div className="min-h-screen flex flex-col bg-slate-50 text-slate-900">
      <header className="bg-slate-900 text-white shadow-md py-4 px-6 flex justify-between items-center border-b border-slate-700">
        <div>
          <h1 className="text-xl font-bold tracking-tight uppercase">Master Furnishings Pvt. Ltd.</h1>
          <p className="text-xs text-slate-400">Lean Management Operational System</p>
        </div>
        <div className="flex items-center gap-6">
          <div className="text-right border-r border-slate-700 pr-6">
            <p className="text-sm font-bold text-blue-400 uppercase">{currentUser.department}</p>
            <p className="text-[10px] text-slate-400 uppercase tracking-widest">{currentUser.role}</p>
          </div>
          <button 
            onClick={handleLogout}
            className="px-4 py-1.5 text-xs font-bold border border-slate-600 hover:bg-slate-800 rounded transition-all uppercase"
          >
            Logout
          </button>
        </div>
      </header>

      <nav className="bg-white border-b border-slate-200 px-6 py-1 flex gap-2 overflow-x-auto no-scrollbar">
        <button 
          onClick={() => setActiveTab('dashboard')}
          className={`px-4 py-3 text-xs font-bold uppercase whitespace-nowrap transition-all border-b-2 ${activeTab === 'dashboard' ? 'border-blue-600 text-blue-600' : 'border-transparent text-slate-500 hover:text-slate-800'}`}
        >
          Dashboard
        </button>
        {currentUser.role === 'DEPARTMENT' && (
          <button 
            onClick={() => setActiveTab('submit')}
            className={`px-4 py-3 text-xs font-bold uppercase whitespace-nowrap transition-all border-b-2 ${activeTab === 'submit' ? 'border-blue-600 text-blue-600' : 'border-transparent text-slate-500 hover:text-slate-800'}`}
          >
            Submit Kaizen
          </button>
        )}
        <button 
          onClick={() => setActiveTab('records')}
          className={`px-4 py-3 text-xs font-bold uppercase whitespace-nowrap transition-all border-b-2 ${activeTab === 'records' ? 'border-blue-600 text-blue-600' : 'border-transparent text-slate-500 hover:text-slate-800'}`}
        >
          Records Management
        </button>
        {currentUser.role === 'ADMIN' && (
          <button 
            onClick={() => setActiveTab('analytics')}
            className={`px-4 py-3 text-xs font-bold uppercase whitespace-nowrap transition-all border-b-2 ${activeTab === 'analytics' ? 'border-blue-600 text-blue-600' : 'border-transparent text-slate-500 hover:text-slate-800'}`}
          >
            Global Analytics
          </button>
        )}
      </nav>

      <main className="flex-1 overflow-auto p-4 md:p-6 pb-24">
        <div className="max-w-7xl mx-auto">
          {activeTab === 'dashboard' && (
            <Dashboard key={currentUser.id} user={currentUser} kaizens={kaizens} />
          )}
          {activeTab === 'submit' && currentUser.role === 'DEPARTMENT' && (
            <KaizenForm department={currentUser.department} onSubmit={addKaizen} />
          )}
          {activeTab === 'records' && (
            <Records 
              key={`${currentUser.id}-records`}
              user={currentUser} 
              kaizens={kaizens} 
              onUpdate={updateKaizen}
            />
          )}
          {activeTab === 'analytics' && currentUser.role === 'ADMIN' && (
            <AdminGlobalAnalytics key="admin-analytics" kaizens={kaizens} />
          )}
        </div>
      </main>

      <footer className="bg-white border-t border-slate-200 py-4 px-6 text-center text-[10px] text-slate-400 fixed bottom-0 left-0 right-0 z-50">
        <div className="flex flex-col md:flex-row justify-between items-center max-w-7xl mx-auto gap-2">
          <p className="uppercase font-medium">© 2025 Master Furnishings Pvt. Ltd. | Proprietary Information</p>
          <div className="flex items-center gap-2">
            <span className="h-1 w-1 bg-slate-300 rounded-full"></span>
            <p className="italic font-bold text-slate-500 uppercase tracking-widest opacity-60">Develop by Hamza Raza</p>
          </div>
        </div>
      </footer>
    </div>
  );
};

export default App;

import React, { useMemo, useState } from 'react';
import { User, Kaizen, KaizenStatus, KaizenType, MONTHS, DEPARTMENTS } from '../types';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer, LineChart, Line, LabelList } from 'recharts';

interface DashboardProps {
  user: User;
  kaizens: Kaizen[];
}

const Dashboard: React.FC<DashboardProps> = ({ user, kaizens }) => {
  const [selectedMonth, setSelectedMonth] = useState<string>('All');
  const [selectedDept, setSelectedDept] = useState<string>(user.role === 'ADMIN' ? 'All' : user.department);

  const filteredKaizens = useMemo(() => {
    return kaizens.filter(k => {
      const monthMatch = selectedMonth === 'All' || k.month === selectedMonth;
      const deptMatch = selectedDept === 'All' || k.department === selectedDept;
      return monthMatch && deptMatch;
    });
  }, [kaizens, selectedMonth, selectedDept]);

  const stats = useMemo(() => {
    const total = filteredKaizens.length;
    const acceptedIdeas = filteredKaizens.filter(k => k.status === KaizenStatus.ACCEPTED && k.type === KaizenType.IDEA).length;
    const acceptedImp = filteredKaizens.filter(k => k.status === KaizenStatus.ACCEPTED && k.type === KaizenType.IMPLEMENTED).length;
    const rejectedIdeas = filteredKaizens.filter(k => k.status === KaizenStatus.REJECTED && k.type === KaizenType.IDEA).length;
    const rejectedImp = filteredKaizens.filter(k => k.status === KaizenStatus.REJECTED && k.type === KaizenType.IMPLEMENTED).length;
    const pending = filteredKaizens.filter(k => k.status === KaizenStatus.PENDING).length;

    const ideaCount = filteredKaizens.filter(k => k.type === KaizenType.IDEA).length;
    const impCount = filteredKaizens.filter(k => k.type === KaizenType.IMPLEMENTED).length;

    const reward = (acceptedIdeas * 50) + (acceptedImp * 200);

    // Fixed Target Calculation
    const systemMonths = Array.from(new Set(kaizens.map(k => k.month)));
    const monthsCount = selectedMonth === 'All' ? Math.max(1, systemMonths.length) : 1;
    const deptsCount = selectedDept === 'All' ? DEPARTMENTS.length : 1;

    const target = monthsCount * deptsCount * 4;
    const participation = target > 0 ? (total / target) * 100 : 0;

    return { 
      total, ideaCount, impCount, acceptedIdeas, acceptedImp, 
      rejectedIdeas, rejectedImp, pending, reward, participation, target 
    };
  }, [filteredKaizens, kaizens, selectedMonth, selectedDept]);

  // Graph 1: Department wise participation
  const chartData = useMemo(() => {
    return DEPARTMENTS.map(dept => {
      const deptKaizens = filteredKaizens.filter(k => k.department === dept);
      const systemMonths = Array.from(new Set(kaizens.map(k => k.month)));
      const monthsCount = selectedMonth === 'All' ? Math.max(1, systemMonths.length) : 1;
      const deptTarget = monthsCount * 4;

      return {
        name: dept,
        submissions: deptKaizens.length,
        target: deptTarget,
      };
    }).filter(d => selectedDept === 'All' ? d.submissions >= 0 : d.name === selectedDept);
  }, [filteredKaizens, kaizens, selectedMonth, selectedDept]);

  // Graph 2: Improved Trend Data Logic
  const comparisonData = useMemo(() => {
    // Collect all months that actually have data
    const systemMonths = Array.from(new Set(kaizens.map(k => k.month)))
      .sort((a, b) => MONTHS.indexOf(a) - MONTHS.indexOf(b));

    // If "All" selected, show all recorded months. If one selected, show selected and previous.
    let monthsToGraph = systemMonths;
    if (selectedMonth !== 'All') {
      const idx = systemMonths.indexOf(selectedMonth);
      if (idx !== -1) {
        monthsToGraph = systemMonths.slice(Math.max(0, idx - 3), idx + 1);
      }
    }

    return monthsToGraph.map(m => {
      const count = kaizens.filter(k => k.month === m && (selectedDept === 'All' || k.department === selectedDept)).length;
      return { month: m, submissions: count };
    });
  }, [kaizens, selectedMonth, selectedDept]);

  return (
    <div className="space-y-6 text-slate-900 animate-in fade-in duration-500">
      <div className="flex flex-wrap gap-4 items-center justify-between bg-white p-5 rounded border border-slate-200 shadow-sm">
        <h2 className="text-xl font-bold text-slate-900 uppercase tracking-tight">
          {user.role === 'ADMIN' ? 'Strategic Global Dashboard' : `Performance Dashboard: ${user.department}`}
        </h2>
        <div className="flex gap-2">
          <select 
            value={selectedMonth} 
            onChange={(e) => setSelectedMonth(e.target.value)}
            className="px-4 py-2 border border-slate-200 rounded text-xs font-bold uppercase bg-slate-50 text-slate-900 outline-none"
          >
            <option value="All">Cumulative View</option>
            {MONTHS.map(m => <option key={m} value={m}>{m}</option>)}
          </select>
          {user.role === 'ADMIN' && (
            <select 
              value={selectedDept} 
              onChange={(e) => setSelectedDept(e.target.value)}
              className="px-4 py-2 border border-slate-200 rounded text-xs font-bold uppercase bg-slate-50 text-slate-900 outline-none"
            >
              <option value="All">All Business Units</option>
              {DEPARTMENTS.map(d => <option key={d} value={d}>{d}</option>)}
            </select>
          )}
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <div className="bg-white p-6 border border-slate-200 shadow-sm rounded flex flex-col justify-between">
          <div>
            <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-1">Total Kaizen Received</p>
            <p className="text-4xl font-extrabold text-slate-900">{stats.total}</p>
          </div>
          <div className="mt-4 pt-3 border-t border-slate-100 space-y-2">
            <div className="flex justify-between text-[10px] font-bold text-slate-500 uppercase">
              <span>Ideas:</span>
              <span className="text-blue-600 font-black">{stats.ideaCount}</span>
            </div>
            <div className="flex justify-between text-[10px] font-bold text-slate-500 uppercase">
              <span>Implemented:</span>
              <span className="text-emerald-600 font-black">{stats.impCount}</span>
            </div>
          </div>
        </div>

        <div className="bg-white p-6 border border-slate-200 shadow-sm rounded">
          <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-1">Participation Rate</p>
          <p className="text-4xl font-extrabold text-blue-600">{stats.participation.toFixed(1)}%</p>
          <p className="text-[10px] font-bold text-slate-400 uppercase mt-2">Submission Goal: {stats.target} Units</p>
        </div>

        <div className="bg-white p-6 border border-slate-200 shadow-sm rounded">
          <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-1">Accrued Rewards</p>
          <p className="text-4xl font-extrabold text-emerald-600">{stats.reward.toLocaleString()}</p>
          <p className="text-[10px] font-bold text-slate-400 uppercase mt-2">Unit: PKR</p>
        </div>

        <div className="bg-white p-6 border-l-4 border-l-amber-500 shadow-sm rounded">
          <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-1">Review Queue</p>
          <p className="text-4xl font-extrabold text-amber-500">{stats.pending}</p>
          <p className="text-[10px] font-bold text-slate-400 uppercase mt-2">Awaiting Approval</p>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <div className="bg-white p-6 border border-slate-200 shadow-sm rounded">
          <h3 className="text-xs font-bold text-slate-900 uppercase mb-6 tracking-widest border-b pb-2">Business Unit Status Breakdown</h3>
          <div className="grid grid-cols-2 gap-4">
