    const total = filteredKaizens.length;
    const acceptedIdeas = filteredKaizens.filter(k => k.status === KaizenStatus.ACCEPTED && k.type === KaizenType.IDEA).length;
    const acceptedImp = filteredKaizens.filter(k => k.status === KaizenStatus.ACCEPTED && k.type === KaizenType.IMPLEMENTED).length;
    const rejectedIdeas = filteredKaizens.filter(k => k.status === KaizenStatus.REJECTED && k.type === KaizenType.IDEA).length;
    const rejectedImp = filteredKaizens.filter(k => k.status === KaizenStatus.REJECTED && k.type === KaizenType.IMPLEMENTED).length;
    const pending = filteredKaizens.filter(k => k.status === KaizenStatus.PENDING).length;

    const ideaCount = filteredKaizens.filter(k => k.type === KaizenType.IDEA).length;
    const impCount = filteredKaizens.filter(k => k.type === KaizenType.IMPLEMENTED).length;

    const reward = (acceptedIdeas * 50) + (acceptedImp * 200);

    const systemMonths = Array.from(new Set(kaizens.map(k => k.month)));
    const monthsCount = selectedMonth === 'All' ? Math.max(1, systemMonths.length) : 1;

    let totalTarget = 0;
    if (selectedDept === 'All') {
      DEPARTMENTS.forEach(d => {
        totalTarget += getDeptMonthlyTarget(d) * monthsCount;
      });
    } else {
      totalTarget = getDeptMonthlyTarget(selectedDept) * monthsCount;
    }

    const participation = totalTarget > 0 ? (total / totalTarget) * 100 : 0;

    // Get latest feedback for department portal
    const latestWithFeedback = [...filteredKaizens]
      .filter(k => k.feedback && k.status !== KaizenStatus.PENDING)
      .sort((a, b) => new Date(b.submissionDate).getTime() - new Date(a.submissionDate).getTime())[0];

    return { 
      total, ideaCount, impCount, acceptedIdeas, acceptedImp, 
      rejectedIdeas, rejectedImp, pending, reward, participation, 
      target: totalTarget, latestFeedback: latestWithFeedback 
    };
  }, [filteredKaizens, kaizens, selectedMonth, selectedDept]);

  const chartData = useMemo(() => {
    return DEPARTMENTS.map(dept => {
      const deptKaizens = filteredKaizens.filter(k => k.department === dept);
      const systemMonths = Array.from(new Set(kaizens.map(k => k.month)));
      const monthsCount = selectedMonth === 'All' ? Math.max(1, systemMonths.length) : 1;
      const deptTarget = getDeptMonthlyTarget(dept) * monthsCount;

      return {
        name: dept,
        submissions: deptKaizens.length,
        target: deptTarget,
      };
    }).filter(d => selectedDept === 'All' ? true : d.name === selectedDept);
  }, [filteredKaizens, kaizens, selectedMonth, selectedDept]);

  const comparisonData = useMemo(() => {
    const systemMonths = Array.from(new Set(kaizens.map(k => k.month)))
      .sort((a: any, b: any) => MONTHS.indexOf(a) - MONTHS.indexOf(b));

    let monthsToGraph = systemMonths;
    if (selectedMonth !== 'All') {
      const idx = systemMonths.indexOf(selectedMonth);
      if (idx !== -1) {
        monthsToGraph = systemMonths.slice(Math.max(0, idx - 3), idx + 1);
      }
    }

    return monthsToGraph.map(m => {
      const count = kaizens.filter(k => k.month === m && (selectedDept === 'All' || k.department === selectedDept)).length;
      return { month: m, submissions: count };
    });
  }, [kaizens, selectedMonth, selectedDept]);

  return (
    <div className="space-y-6 text-slate-900 animate-in fade-in duration-500">
      <div className="flex flex-wrap gap-4 items-center justify-between bg-white p-5 rounded border border-slate-200 shadow-sm">
        <h2 className="text-xl font-bold text-slate-900 uppercase tracking-tight">
          {user.role === 'ADMIN' ? 'Strategic Global Dashboard' : `Performance Dashboard: ${user.department}`}
        </h2>
        <div className="flex gap-2">
          <select 
            value={selectedMonth} 
            onChange={(e) => setSelectedMonth(e.target.value)}
            className="px-4 py-2 border border-slate-200 rounded text-xs font-bold uppercase bg-slate-50 text-slate-900 outline-none"
          >
            <option value="All">Cumulative View</option>
            {MONTHS.map(m => <option key={m} value={m}>{m}</option>)}
          </select>
          {user.role === 'ADMIN' && (
            <select 
              value={selectedDept} 
              onChange={(e) => setSelectedDept(e.target.value)}
              className="px-4 py-2 border border-slate-200 rounded text-xs font-bold uppercase bg-slate-50 text-slate-900 outline-none"
            >
              <option value="All">All Business Units</option>
              {DEPARTMENTS.map(d => <option key={d} value={d}>{d}</option>)}
            </select>
          )}
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <div className="bg-white p-6 border border-slate-200 shadow-sm rounded flex flex-col justify-between">
          <div>
            <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-1">Total Kaizen Received</p>
            <p className="text-4xl font-extrabold text-slate-900">{stats.total}</p>
          </div>
          <div className="mt-4 pt-3 border-t border-slate-100 space-y-2">
            <div className="flex justify-between text-[10px] font-bold text-slate-500 uppercase">
              <span>Ideas:</span>
              <span className="text-blue-600 font-black">{stats.ideaCount}</span>
            </div>
            <div className="flex justify-between text-[10px] font-bold text-slate-500 uppercase">
              <span>Implemented:</span>
              <span className="text-emerald-600 font-black">{stats.impCount}</span>
            </div>
          </div>
        </div>

        <div className="bg-white p-6 border border-slate-200 shadow-sm rounded">
          <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-1">Participation Rate</p>
          <p className="text-4xl font-extrabold text-blue-600">{stats.participation.toFixed(1)}%</p>
          <p className="text-[10px] font-bold text-slate-400 uppercase mt-2">Submission Target: {stats.target} Units</p>
        </div>

        <div className="bg-white p-6 border border-slate-200 shadow-sm rounded">
          <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-1">Accrued Rewards</p>
          <p className="text-4xl font-extrabold text-emerald-600">{stats.reward.toLocaleString()}</p>
          <p className="text-[10px] font-bold text-slate-400 uppercase mt-2">Unit: PKR</p>
        </div>

        <div className="bg-white p-6 border-l-4 border-l-amber-500 shadow-sm rounded">
          <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-1">Review Queue</p>
          <p className="text-4xl font-extrabold text-amber-500">{stats.pending}</p>
          <p className="text-[10px] font-bold text-slate-400 uppercase mt-2">Awaiting Decision</p>
        </div>
      </div>

      {user.role === 'DEPARTMENT' && stats.latestFeedback && (
        <div className="bg-blue-50 border border-blue-200 p-6 rounded shadow-sm">
          <div className="flex items-center gap-2 mb-3">
            <span className="h-2 w-2 bg-blue-600 rounded-full animate-pulse"></span>
            <h3 className="text-[11px] font-black text-blue-900 uppercase tracking-widest">Latest Feedback from Lean Department</h3>
          </div>
          <div className="bg-white p-4 rounded border border-blue-100 italic text-slate-700 text-sm shadow-inner">
            "{stats.latestFeedback.feedback}"
            <div className="mt-2 text-[9px] font-bold text-slate-400 uppercase not-italic">
              Regarding: {stats.latestFeedback.type} submitted on {stats.latestFeedback.submissionDate} ({stats.latestFeedback.status})
            </div>
          </div>
        </div>
      )}

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <div className="bg-white p-6 border border-slate-200 shadow-sm rounded">
          <h3 className="text-xs font-bold text-slate-900 uppercase mb-6 tracking-widest border-b pb-2">Business Unit Status Breakdown</h3>
          <div className="grid grid-cols-2 gap-4">
            <div className="p-3 bg-emerald-50 border border-emerald-100 rounded text-center">
              <span className="text-[10px] font-bold text-emerald-800 uppercase block mb-1">Accepted Idea</span>
              <span className="text-xl font-black text-emerald-700">{stats.acceptedIdeas}</span>
            </div>
            <div className="p-3 bg-emerald-100 border border-emerald-200 rounded text-center">
              <span className="text-[10px] font-bold text-emerald-900 uppercase block mb-1">Accepted Imp.</span>
              <span className="text-xl font-black text-emerald-800">{stats.acceptedImp}</span>
            </div>
            <div className="p-3 bg-red-50 border border-red-100 rounded text-center">
              <span className="text-[10px] font-bold text-red-800 uppercase block mb-1">Rejected Idea</span>
              <span className="text-xl font-black text-red-700">{stats.rejectedIdeas}</span>
            </div>
            <div className="p-3 bg-red-100 border border-red-200 rounded text-center">
              <span className="text-[10px] font-bold text-red-900 uppercase block mb-1">Rejected Imp.</span>
              <span className="text-xl font-black text-red-800">{stats.rejectedImp}</span>
            </div>
          </div>
        </div>

        <div className="bg-white p-6 border border-slate-200 shadow-sm rounded">
          <h3 className="text-xs font-bold text-slate-900 uppercase mb-6 tracking-widest border-b pb-2">Department Performance Overview</h3>
          <div className="h-48">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={chartData} margin={{ top: 20, right: 30, left: 0, bottom: 20 }}>
                <CartesianGrid strokeDasharray="2 2" vertical={false} stroke="#f1f5f9" />
                <XAxis 
                  dataKey="name" 
                  fontSize={8} 
                  fontWeight="bold" 
                  angle={-45} 
                  textAnchor="end" 
                  interval={0}
                  height={60}
                />
                <YAxis fontSize={10} axisLine={false} tickLine={false} />
                <Tooltip />
                <Bar dataKey="submissions" name="Submissions" fill="#1e293b" radius={[2, 2, 0, 0]}>
                  <LabelList dataKey="submissions" position="top" style={{ fontSize: '10px', fontWeight: 'bold', fill: '#1e293b' }} />
                </Bar>
                <Bar dataKey="target" name="Goal" fill="#cbd5e1" radius={[2, 2, 0, 0]} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>

      <div className="bg-white p-6 border border-slate-200 shadow-sm rounded">
        <h3 className="text-xs font-bold text-slate-900 uppercase mb-6 tracking-widest border-b pb-2">Fiscal Performance Trend</h3>
        <div className="h-64">
          <ResponsiveContainer width="100%" height="100%">
            <LineChart data={comparisonData} margin={{ top: 20, right: 30, left: 20, bottom: 20 }}>
              <CartesianGrid strokeDasharray="2 2" vertical={false} stroke="#f1f5f9" />
              <XAxis dataKey="month" fontSize={10} fontWeight="bold" />
              <YAxis fontSize={10} axisLine={false} tickLine={false} />
              <Tooltip />
              <Line 
                type="monotone" 
                dataKey="submissions" 
                name="Monthly Units" 
                stroke="#2563eb" 
                strokeWidth={3} 
                dot={{ r: 6, fill: '#2563eb', strokeWidth: 2, stroke: '#fff' }} 
              >
                <LabelList dataKey="submissions" position="top" offset={10} style={{ fontSize: '10px', fontWeight: 'bold', fill: '#2563eb' }} />
              </Line>
            </LineChart>
          </ResponsiveContainer>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useMemo, useState } from 'react';
import { Kaizen, KaizenStatus, KaizenType, DEPARTMENTS, MONTHS } from '../types';

interface AdminGlobalAnalyticsProps {
  kaizens: Kaizen[];
}

const AdminGlobalAnalytics: React.FC<AdminGlobalAnalyticsProps> = ({ kaizens }) => {
  const [selectedMonth, setSelectedMonth] = useState<string>('All');

  const getDeptMonthlyTarget = (deptName: string) => {
    if (deptName === 'Admin' || deptName === 'PPMC') return 2;
    return 4;
  };

  const analytics = useMemo(() => {
    return DEPARTMENTS.map(dept => {
      const deptKaizens = kaizens.filter(k => 
        (selectedMonth === 'All' || k.month === selectedMonth) && 
        k.department === dept
      );

      const systemMonths = Array.from(new Set(kaizens.map(k => k.month)));
      const monthsCount = selectedMonth === 'All' ? Math.max(1, systemMonths.length) : 1;
      const target = getDeptMonthlyTarget(dept) * monthsCount;

      const accIdeas = deptKaizens.filter(k => k.status === KaizenStatus.ACCEPTED && k.type === KaizenType.IDEA).length;
      const accImp = deptKaizens.filter(k => k.status === KaizenStatus.ACCEPTED && k.type === KaizenType.IMPLEMENTED).length;
      const rejIdeas = deptKaizens.filter(k => k.status === KaizenStatus.REJECTED && k.type === KaizenType.IDEA).length;
      const rejImp = deptKaizens.filter(k => k.status === KaizenStatus.REJECTED && k.type === KaizenType.IMPLEMENTED).length;
      const pending = deptKaizens.filter(k => k.status === KaizenStatus.PENDING).length;

      const participation = target > 0 ? (deptKaizens.length / target) * 100 : 0;
      const totalReward = (accIdeas * 50) + (accImp * 200);

      return {
        dept,
        total: deptKaizens.length,
        accIdeas,
        accImp,
        rejIdeas,
        rejImp,
        pending,
        participation,
        totalReward,
        target
      };
    }).sort((a, b) => b.participation - a.participation);
  }, [kaizens, selectedMonth]);

  const totals = useMemo(() => {
    const sumPart = analytics.reduce((acc, curr) => acc + curr.participation, 0);
    const avgPart = DEPARTMENTS.length > 0 ? sumPart / DEPARTMENTS.length : 0;

    const baseTotals = analytics.reduce((acc, curr) => ({
      total: acc.total + curr.total,
      accIdeas: acc.accIdeas + curr.accIdeas,
      accImp: acc.accImp + curr.accImp,
      rejIdeas: acc.rejIdeas + curr.rejIdeas,
      rejImp: acc.rejImp + curr.rejImp,
      reward: acc.reward + curr.totalReward
    }), { total: 0, accIdeas: 0, accImp: 0, rejIdeas: 0, rejImp: 0, reward: 0 });

    return { ...baseTotals, avgPart };
  }, [analytics]);

  return (
    <div className="space-y-6 animate-in slide-in-from-bottom-4 duration-500 pb-12">
      <div className="flex flex-col md:flex-row justify-between items-center bg-white p-5 rounded border border-slate-200 shadow-sm gap-4">
        <h2 className="text-xl font-bold text-slate-900 tracking-tight uppercase">Strategic Unit Performance Center</h2>
        <select 
          value={selectedMonth} 
          onChange={(e) => setSelectedMonth(e.target.value)}
          className="w-full md:w-auto px-4 py-2 border border-slate-200 rounded text-xs font-bold uppercase bg-slate-50 text-slate-900 outline-none"
        >
          <option value="All">Cumulative Fiscal View</option>
          {MONTHS.map(m => <option key={m} value={m}>{m}</option>)}
        </select>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="bg-slate-900 p-6 rounded shadow-lg text-white border-l-4 border-blue-500">
          <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-1">Company Avg Participation</p>
          <p className="text-4xl font-extrabold text-blue-400">{totals.avgPart.toFixed(1)}%</p>
          <p className="text-[10px] font-bold text-slate-500 uppercase mt-2">Aggregated Goal Achievement</p>
        </div>
        <div className="bg-white p-6 rounded border border-slate-200 shadow-sm">
          <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-1">Consolidated Submissions</p>
          <p className="text-4xl font-extrabold text-slate-900">{totals.total}</p>
          <p className="text-[10px] font-bold text-slate-400 uppercase mt-2">Ideas: {totals.accIdeas + totals.rejIdeas} | Impl: {totals.accImp + totals.rejImp}</p>
        </div>
        <div className="bg-blue-900 p-6 rounded shadow-lg text-white">
          <p className="text-[10px] font-bold text-blue-300 uppercase tracking-widest mb-1">Total Reward Liability</p>
          <p className="text-4xl font-extrabold">{totals.reward.toLocaleString()} <span className="text-sm">PKR</span></p>
          <p className="text-[10px] font-bold text-blue-400 uppercase mt-2">Finance Approved Total</p>
        </div>
      </div>

      <div className="bg-white rounded border border-slate-200 shadow-sm overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse min-w-[1000px]">
            <thead>
              <tr className="bg-slate-900 text-white uppercase text-[9px] tracking-widest font-bold">
                <th className="px-4 py-5 border-r border-slate-800">Business Unit</th>
                <th className="px-4 py-5 border-r border-slate-800 text-center">Participation %</th>
                <th className="px-4 py-5 border-r border-slate-800 text-center">Unit Target Meta</th>
                <th className="px-4 py-5 border-r border-slate-800 text-center text-emerald-400">Acc. Idea</th>
                <th className="px-4 py-5 border-r border-slate-800 text-center text-emerald-400">Acc. Imp.</th>
                <th className="px-4 py-5 border-r border-slate-800 text-center text-red-400">Rej. Idea</th>
                <th className="px-4 py-5 border-r border-slate-800 text-center text-red-400">Rej. Imp.</th>
                <th className="px-4 py-5 border-r border-slate-800 text-center text-amber-400">In Review</th>
                <th className="px-4 py-5 text-right">Value (PKR)</th>
              </tr>
            </thead>
            <tbody className="text-[11px] divide-y divide-slate-100">
              {analytics.map(row => (
                <tr key={row.dept} className="hover:bg-slate-50 transition-colors">
                  <td className="px-4 py-5 border-r border-slate-100 font-extrabold text-slate-900">{row.dept}</td>
                  <td className="px-4 py-5 border-r border-slate-100">
                    <div className="flex items-center gap-3 justify-center">
                      <div className="w-20 bg-slate-100 rounded-full h-1.5 overflow-hidden">
                        <div 
                          className={`h-full ${row.participation >= 100 ? 'bg-emerald-500' : 'bg-blue-600'}`} 
                          style={{ width: `${Math.min(100, row.participation)}%` }} 
                        />
                      </div>
                      <span className="font-black text-[10px] w-10">{row.participation.toFixed(1)}%</span>
                    </div>
                  </td>
                  <td className="px-4 py-5 border-r border-slate-100 text-center font-bold text-slate-500">{row.total} / {row.target}</td>
                  <td className="px-4 py-5 border-r border-slate-100 text-center text-emerald-700 font-black">{row.accIdeas}</td>
                  <td className="px-4 py-5 border-r border-slate-100 text-center text-emerald-700 font-black">{row.accImp}</td>
                  <td className="px-4 py-5 border-r border-slate-100 text-center text-red-500 font-bold">{row.rejIdeas}</td>
                  <td className="px-4 py-5 border-r border-slate-100 text-center text-red-500 font-bold">{row.rejImp}</td>
                  <td className="px-4 py-5 border-r border-slate-100 text-center text-amber-600 font-black bg-amber-50/30">{row.pending}</td>
                  <td className="px-4 py-5 text-right font-black text-slate-900">{row.totalReward.toLocaleString()}</td>
                </tr>
              ))}
            </tbody>
            <tfoot className="bg-slate-50 border-t-2 border-slate-200 uppercase font-black text-[10px] tracking-widest">
              <tr className="text-slate-900">
                <td className="px-4 py-6 border-r border-slate-200">Consolidated Summary</td>
                <td className="px-4 py-6 border-r border-slate-200 text-center text-blue-600">{totals.avgPart.toFixed(1)}% Avg</td>
                <td className="px-4 py-6 border-r border-slate-200 text-center">{totals.total} Units</td>
                <td className="px-4 py-6 border-r border-slate-200 text-center">{totals.accIdeas}</td>
                <td className="px-4 py-6 border-r border-slate-200 text-center">{totals.accImp}</td>
                <td className="px-4 py-6 border-r border-slate-200 text-center">{totals.rejIdeas}</td>
                <td className="px-4 py-6 border-r border-slate-200 text-center">{totals.rejImp}</td>
                <td className="px-4 py-6 border-r border-slate-200 text-center"></td>
                <td className="px-4 py-6 text-right text-blue-800 text-lg">{totals.reward.toLocaleString()} PKR</td>
              </tr>
            </tfoot>
          </table>
        </div>
      </div>
    </div>
  );
};

export default AdminGlobalAnalytics;

