import React, { useMemo, useState } from 'react';
import { User, Kaizen, KaizenStatus, KaizenType, MONTHS, DEPARTMENTS } from '../types';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer, LineChart, Line, LabelList } from 'recharts';

interface DashboardProps {
  user: User;
  kaizens: Kaizen[];
}

const Dashboard: React.FC<DashboardProps> = ({ user, kaizens }) => {
  const [selectedMonth, setSelectedMonth] = useState<string>('All');
  const [selectedDept, setSelectedDept] = useState<string>(user.role === 'ADMIN' ? 'All' : user.department);

  const getDeptMonthlyTarget = (deptName: string) => {
    if (deptName === 'Admin' || deptName === 'PPMC') return 2;
    return 4;
  };

  const filteredKaizens = useMemo(() => {
    return kaizens.filter(k => {
      const monthMatch = selectedMonth === 'All' || k.month === selectedMonth;
      const deptMatch = selectedDept === 'All' || k.department === selectedDept;
      return monthMatch && deptMatch;
    });
  }, [kaizens, selectedMonth, selectedDept]);

  const stats = useMemo(() => {
    const total = filteredKaizens.length;
    const accIdeas = filteredKaizens.filter(k => k.status === KaizenStatus.ACCEPTED && k.type === KaizenType.IDEA).length;
    const accImp = filteredKaizens.filter(k => k.status === KaizenStatus.ACCEPTED && k.type === KaizenType.IMPLEMENTED).length;
    const rejIdeas = filteredKaizens.filter(k => k.status === KaizenStatus.REJECTED && k.type === KaizenType.IDEA).length;
    const rejImp = filteredKaizens.filter(k => k.status === KaizenStatus.REJECTED && k.type === KaizenType.IMPLEMENTED).length;
    const pending = filteredKaizens.filter(k => k.status === KaizenStatus.PENDING).length;

    const reward = (accIdeas * 50) + (accImp * 200);

    const activeMonthsInSystem = Array.from(new Set(kaizens.map(k => k.month)));
    const monthsCount = selectedMonth === 'All' ? Math.max(1, activeMonthsInSystem.length) : 1;

    let baseTarget = 0;
    if (selectedDept === 'All') {
      DEPARTMENTS.forEach(d => baseTarget += getDeptMonthlyTarget(d) * monthsCount);
    } else {
      baseTarget = getDeptMonthlyTarget(selectedDept) * monthsCount;
    }

    const participation = baseTarget > 0 ? (total / baseTarget) * 100 : 0;

    return { 
      total, accIdeas, accImp, rejIdeas, rejImp, pending, reward, participation, target: baseTarget 
    };
  }, [filteredKaizens, kaizens, selectedMonth, selectedDept]);

  const deptChartData = useMemo(() => {
    const systemMonths = Array.from(new Set(kaizens.map(k => k.month)));
    const monthsCount = selectedMonth === 'All' ? Math.max(1, systemMonths.length) : 1;

    return DEPARTMENTS.map(dept => {
      const submissions = kaizens.filter(k => 
        k.department === dept && (selectedMonth === 'All' || k.month === selectedMonth)
      ).length;
      return {
        name: dept,
        submissions,
        target: getDeptMonthlyTarget(dept) * monthsCount
      };
    }).filter(d => selectedDept === 'All' ? true : d.name === selectedDept);
  }, [kaizens, selectedMonth, selectedDept]);

  const trendData = useMemo(() => {
    const activeMonths = Array.from(new Set(kaizens.map(k => k.month)))
      .sort((a: any, b: any) => MONTHS.indexOf(a) - MONTHS.indexOf(b));

    return activeMonths.map(m => ({
      month: m,
      count: kaizens.filter(k => k.month === m && (selectedDept === 'All' || k.department === selectedDept)).length
    }));
  }, [kaizens, selectedDept]);

  return (
    <div className="space-y-6 text-slate-900 animate-in fade-in duration-700">
