import React, { useMemo, useState } from 'react';
import { User, Kaizen, KaizenStatus, KaizenType, MONTHS, DEPARTMENTS } from '../types';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer, Cell } from 'recharts';

interface DashboardProps {
  user: User;
  kaizens: Kaizen[];
}

const Dashboard: React.FC<DashboardProps> = ({ user, kaizens }) => {
  const [selectedMonth, setSelectedMonth] = useState<string>('All');
  const [selectedDept, setSelectedDept] = useState<string>(user.role === 'ADMIN' ? 'All' : user.department);

  const getDeptMonthlyTarget = (deptName: string) => {
    if (deptName === 'Admin' || deptName === 'PPMC' || deptName === 'HSE') return 2;
    return 4;
  };

  const filteredKaizens = useMemo(() => {
    return kaizens.filter(k => {
      const monthMatch = selectedMonth === 'All' || k.month === selectedMonth;
      const deptMatch = selectedDept === 'All' || k.department === selectedDept;
      return monthMatch && deptMatch;
    });
  }, [kaizens, selectedMonth, selectedDept]);

  const activeMonthsInSystem = useMemo(() => {
    const months = Array.from(new Set(kaizens.map(k => k.month)));
    return months.sort((a, b) => MONTHS.indexOf(a) - MONTHS.indexOf(b));
  }, [kaizens]);

  const stats = useMemo(() => {
    const total = filteredKaizens.length;
    const accIdeas = filteredKaizens.filter(k => k.status === KaizenStatus.ACCEPTED && k.type === KaizenType.IDEA).length;
    const accImp = filteredKaizens.filter(k => k.status === KaizenStatus.ACCEPTED && k.type === KaizenType.IMPLEMENTED).length;
    const rejIdeas = filteredKaizens.filter(k => k.status === KaizenStatus.REJECTED && k.type === KaizenType.IDEA).length;
    const rejImp = filteredKaizens.filter(k => k.status === KaizenStatus.REJECTED && k.type === KaizenType.IMPLEMENTED).length;
    const pending = filteredKaizens.filter(k => k.status === KaizenStatus.PENDING).length;

    const reward = (accIdeas * 50) + (accImp * 200);

    const monthsCount = selectedMonth === 'All' ? Math.max(1, activeMonthsInSystem.length) : 1;

    let baseTarget = 0;
    if (selectedDept === 'All') {
      DEPARTMENTS.forEach(d => baseTarget += getDeptMonthlyTarget(d) * monthsCount);
    } else {
      baseTarget = getDeptMonthlyTarget(selectedDept) * monthsCount;
    }

    const participation = baseTarget > 0 ? (total / baseTarget) * 100 : 0;

    return { 
      total, accIdeas, accImp, rejIdeas, rejImp, pending, reward, participation, target: baseTarget,
      totalIdeas: filteredKaizens.filter(k => k.type === KaizenType.IDEA).length,
      totalImp: filteredKaizens.filter(k => k.type === KaizenType.IMPLEMENTED).length
    };
  }, [filteredKaizens, activeMonthsInSystem, selectedMonth, selectedDept]);

  const deptParticipationData = useMemo(() => {
    const monthsCount = selectedMonth === 'All' ? Math.max(1, activeMonthsInSystem.length) : 1;
    return DEPARTMENTS.map(dept => {
      const submissions = kaizens.filter(k => 
        k.department === dept && (selectedMonth === 'All' || k.month === selectedMonth)
      ).length;
      const target = getDeptMonthlyTarget(dept) * monthsCount;
      return {
        name: dept,
        participation: target > 0 ? (submissions / target) * 100 : 0
      };
    }).filter(d => selectedDept === 'All' ? true : d.name === selectedDept)
      .sort((a, b) => b.participation - a.participation);
  }, [kaizens, selectedMonth, activeMonthsInSystem, selectedDept]);

  const comparisonData = useMemo(() => {
    if (selectedMonth === 'All' || activeMonthsInSystem.length < 2) return [];

    const currentIndex = MONTHS.indexOf(selectedMonth);
    if (currentIndex <= 0) return [];

    const prevMonth = MONTHS[currentIndex - 1];

    const currentCount = kaizens.filter(k => k.month === selectedMonth && (selectedDept === 'All' || k.department === selectedDept)).length;
    const prevCount = kaizens.filter(k => k.month === prevMonth && (selectedDept === 'All' || k.department === selectedDept)).length;

    return [
      { name: prevMonth, count: prevCount, type: 'Previous' },
      { name: selectedMonth, count: currentCount, type: 'Current' }
    ];
  }, [kaizens, selectedMonth, activeMonthsInSystem, selectedDept]);

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row gap-4 items-center justify-between bg-white p-6 rounded-lg border border-slate-200 shadow-sm">
        <div>
          <h2 className="text-2xl font-black text-slate-900 uppercase tracking-tight">
            {user.role === 'ADMIN' ? 'Lean Management Analytics' : `${user.department} Unit Portal`}
          </h2>
          <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-1">Master Furnishings Pvt. Ltd.</p>
        </div>
        <div className="flex gap-3">
          <select 
            value={selectedMonth} 
            onChange={(e) => setSelectedMonth(e.target.value)}
            className="px-4 py-2 border border-slate-200 rounded text-[10px] font-black uppercase bg-slate-50 text-slate-900 outline-none hover:border-blue-500 transition-all shadow-sm"
          >
            <option value="All">All Active Months</option>
            {activeMonthsInSystem.map(m => <option key={m} value={m}>{m}</option>)}
          </select>
          {user.role === 'ADMIN' && (
            <select 
              value={selectedDept} 
              onChange={(e) => setSelectedDept(e.target.value)}
              className="px-4 py-2 border border-slate-200 rounded text-[10px] font-black uppercase bg-slate-50 text-slate-900 outline-none hover:border-blue-500 transition-all shadow-sm"
            >
              <option value="All">All Departments</option>
              {DEPARTMENTS.map(d => <option key={d} value={d}>{d}</option>)}
            </select>
          )}
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <div className="bg-white p-6 border border-slate-200 shadow-sm rounded-lg relative overflow-hidden">
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Total Received</p>
          <p className="text-4xl font-black text-slate-900">{stats.total}</p>
          <div className="mt-4 pt-3 border-t border-slate-100 flex gap-4">
             <div>
               <span className="text-[9px] font-bold text-slate-400 uppercase block">Ideas</span>
               <span className="text-sm font-black text-blue-600">{stats.totalIdeas}</span>
             </div>
             <div>
               <span className="text-[9px] font-bold text-slate-400 uppercase block">Implemented</span>
               <span className="text-sm font-black text-emerald-600">{stats.totalImp}</span>
             </div>
          </div>
        </div>

        <div className="bg-white p-6 border border-slate-200 shadow-sm rounded-lg">
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Participation</p>
          <p className="text-4xl font-black text-blue-600">{stats.participation.toFixed(1)}%</p>
          <p className="text-[10px] font-bold text-slate-400 uppercase mt-2">Target: {stats.target} Kaizens</p>
        </div>

        <div className="bg-white p-6 border border-slate-200 shadow-sm rounded-lg">
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Accrued Rewards</p>
          <p className="text-4xl font-black text-emerald-600">{stats.reward.toLocaleString()}</p>
          <p className="text-[10px] font-bold text-slate-400 uppercase mt-2">Currency: PKR</p>
        </div>

        <div className="bg-white p-6 border-l-4 border-l-amber-500 shadow-sm rounded-lg">
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Pending Review</p>
          <p className="text-4xl font-black text-amber-500">{stats.pending}</p>
          <p className="text-[10px] font-bold text-slate-400 uppercase mt-2">Decisions Awaited</p>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <div className="bg-white p-6 border border-slate-200 shadow-sm rounded-lg">
          <h3 className="text-[11px] font-black text-slate-900 uppercase mb-6 tracking-widest border-b pb-2 flex justify-between">
            Decision Breakup Matrix
            <span className="text-[9px] text-slate-400 font-bold">Summary View</span>
          </h3>
          <div className="grid grid-cols-2 gap-4">
            <div className="p-4 bg-emerald-50 border border-emerald-100 rounded-lg">
              <span className="text-[10px] font-black text-emerald-800 uppercase block mb-1">Accepted Idea</span>
              <span className="text-2xl font-black text-emerald-700">{stats.accIdeas}</span>
              <span className="text-[9px] text-emerald-600 block">Reward: {stats.accIdeas * 50} PKR</span>
            </div>
            <div className="p-4 bg-emerald-100 border border-emerald-200 rounded-lg">
              <span className="text-[10px] font-black text-emerald-900 uppercase block mb-1">Accepted Impl.</span>
              <span className="text-2xl font-black text-emerald-800">{stats.accImp}</span>
              <span className="text-[9px] text-emerald-700 block">Reward: {stats.accImp * 200} PKR</span>
            </div>
            <div className="p-4 bg-red-50 border border-red-100 rounded-lg">
              <span className="text-[10px] font-black text-red-800 uppercase block mb-1">Rejected Idea</span>
              <span className="text-2xl font-black text-red-700">{stats.rejIdeas}</span>
            </div>
            <div className="p-4 bg-red-100 border border-red-200 rounded-lg">
              <span className="text-[10px] font-black text-red-900 uppercase block mb-1">Rejected Impl.</span>
              <span className="text-2xl font-black text-red-800">{stats.rejImp}</span>
            </div>
          </div>
        </div>

        <div className="bg-white p-6 border border-slate-200 shadow-sm rounded-lg flex flex-col">
          <h3 className="text-[11px] font-black text-slate-900 uppercase mb-6 tracking-widest border-b pb-2">Business Unit Participation %</h3>
          <div className="flex-1 h-64">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={deptParticipationData} layout="vertical" margin={{ left: 40, right: 30 }}>
                <CartesianGrid strokeDasharray="1 1" horizontal={false} stroke="#f1f5f9" />
                <XAxis type="number" domain={[0, 100]} fontSize={10} hide />
                <YAxis dataKey="name" type="category" fontSize={9} fontWeight="900" width={80} axisLine={false} tickLine={false} />
                <Tooltip cursor={{fill: '#f8fafc'}} />
                <Bar dataKey="participation" name="Participation %" radius={[0, 4, 4, 0]}>
                  {deptParticipationData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={entry.participation >= 100 ? '#10b981' : '#3b82f6'} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>

      {comparisonData.length > 0 && (
        <div className="bg-white p-6 border border-slate-200 shadow-sm rounded-lg">
          <h3 className="text-[11px] font-black text-slate-900 uppercase mb-6 tracking-widest border-b pb-2">Month-over-Month Comparison</h3>
          <div className="h-64">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={comparisonData} margin={{ top: 20, right: 30, left: 20, bottom: 5 }}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} />
                <XAxis dataKey="name" fontSize={10} fontWeight="900" />
                <YAxis fontSize={10} axisLine={false} tickLine={false} />
                <Tooltip />
                <Legend iconType="circle" wrapperStyle={{ fontSize: '10px', fontWeight: 'bold', textTransform: 'uppercase' }} />
                <Bar dataKey="count" name="Submission Volume" fill="#1e293b" radius={[4, 4, 0, 0]} barSize={60} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>
      )}
    </div>
  );
};

export default Dashboard;

import React, { useMemo, useState } from 'react';
import { Kaizen, KaizenStatus, KaizenType, DEPARTMENTS, MONTHS } from '../types';

interface AdminGlobalAnalyticsProps {
  kaizens: Kaizen[];
}

const AdminGlobalAnalytics: React.FC<AdminGlobalAnalyticsProps> = ({ kaizens }) => {
  const [selectedMonth, setSelectedMonth] = useState<string>('All');

  const getDeptMonthlyTarget = (deptName: string) => {
    if (deptName === 'Admin' || deptName === 'PPMC' || deptName === 'HSE') return 2;
    return 4;
  };

  const activeMonthsInSystem = useMemo(() => {
    const months = Array.from(new Set(kaizens.map(k => k.month)));
    return months.sort((a, b) => MONTHS.indexOf(a) - MONTHS.indexOf(b));
  }, [kaizens]);

  const analytics = useMemo(() => {
    return DEPARTMENTS.map(dept => {
      const deptKaizens = kaizens.filter(k => 
        (selectedMonth === 'All' || k.month === selectedMonth) && 
        k.department === dept
      );

      const monthsCount = selectedMonth === 'All' ? Math.max(1, activeMonthsInSystem.length) : 1;
      const target = getDeptMonthlyTarget(dept) * monthsCount;

      const accIdeas = deptKaizens.filter(k => k.status === KaizenStatus.ACCEPTED && k.type === KaizenType.IDEA).length;
      const accImp = deptKaizens.filter(k => k.status === KaizenStatus.ACCEPTED && k.type === KaizenType.IMPLEMENTED).length;
      const rejIdeas = deptKaizens.filter(k => k.status === KaizenStatus.REJECTED && k.type === KaizenType.IDEA).length;
      const rejImp = deptKaizens.filter(k => k.status === KaizenStatus.REJECTED && k.type === KaizenType.IMPLEMENTED).length;
      const pending = deptKaizens.filter(k => k.status === KaizenStatus.PENDING).length;

      const participation = target > 0 ? (deptKaizens.length / target) * 100 : 0;
      const totalReward = (accIdeas * 50) + (accImp * 200);

      return {
        dept,
        total: deptKaizens.length,
        accIdeas,
        accImp,
        rejIdeas,
        rejImp,
        pending,
        participation,
        totalReward,
        target
      };
    }).sort((a, b) => b.participation - a.participation);
  }, [kaizens, selectedMonth, activeMonthsInSystem]);

  const totals = useMemo(() => {
    const baseTotals = analytics.reduce((acc, curr) => ({
      total: acc.total + curr.total,
      accIdeas: acc.accIdeas + curr.accIdeas,
      accImp: acc.accImp + curr.accImp,
      rejIdeas: acc.rejIdeas + curr.rejIdeas,
      rejImp: acc.rejImp + curr.rejImp,
      pending: acc.pending + curr.pending,
      reward: acc.reward + curr.totalReward
    }), { total: 0, accIdeas: 0, accImp: 0, rejIdeas: 0, rejImp: 0, pending: 0, reward: 0 });

    const avgPart = DEPARTMENTS.length > 0 ? analytics.reduce((s, c) => s + c.participation, 0) / DEPARTMENTS.length : 0;

    return { ...baseTotals, avgPart };
  }, [analytics]);

  return (
    <div className="space-y-6 pb-20">
      <div className="flex flex-col md:flex-row justify-between items-center bg-white p-5 rounded border border-slate-200 shadow-sm gap-4">
        <h2 className="text-xl font-bold text-slate-900 tracking-tight uppercase">Master Furnishings Unit Performance</h2>
        <select 
          value={selectedMonth} 
          onChange={(e) => setSelectedMonth(e.target.value)}
          className="w-full md:w-auto px-4 py-2 border border-slate-200 rounded text-xs font-bold uppercase bg-slate-50 text-slate-900 outline-none"
        >
          <option value="All">All Active Reporting Periods</option>
          {activeMonthsInSystem.map(m => <option key={m} value={m}>{m}</option>)}
        </select>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        <div className="bg-slate-900 p-5 rounded shadow text-white border-l-4 border-blue-500">
          <p className="text-[9px] font-bold text-slate-400 uppercase tracking-widest mb-1">Company Avg Participation</p>
          <p className="text-3xl font-black text-blue-400">{totals.avgPart.toFixed(1)}%</p>
        </div>
        <div className="bg-white p-5 rounded border border-slate-200 shadow-sm">
          <p className="text-[9px] font-bold text-slate-400 uppercase tracking-widest mb-1">Total Submissions</p>
          <p className="text-3xl font-black text-slate-900">{totals.total}</p>
        </div>
        <div className="bg-emerald-900 p-5 rounded shadow text-white">
          <p className="text-[9px] font-bold text-emerald-300 uppercase tracking-widest mb-1">Accepted Count</p>
          <p className="text-3xl font-black text-emerald-400">{totals.accIdeas + totals.accImp}</p>
        </div>
        <div className="bg-amber-600 p-5 rounded shadow text-white">
          <p className="text-[9px] font-bold text-amber-100 uppercase tracking-widest mb-1">Pending Review</p>
          <p className="text-3xl font-black text-white">{totals.pending}</p>
        </div>
      </div>

      <div className="bg-white p-6 rounded border border-slate-200 shadow-sm">
         <div className="flex justify-between items-end mb-4">
           <div>
             <h3 className="text-xs font-black uppercase text-slate-400 tracking-widest">Financial Summary</h3>
             <p className="text-2xl font-black text-slate-900">{totals.reward.toLocaleString()} <span className="text-xs">PKR</span></p>
           </div>
           <div className="text-right text-[10px] text-slate-500 uppercase font-bold">
              Breakup: {(totals.accIdeas * 50).toLocaleString()} (Ideas) + {(totals.accImp * 200).toLocaleString()} (Imp)
           </div>
         </div>
      </div>

      <div className="bg-white rounded border border-slate-200 shadow-sm overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse min-w-[1000px]">
            <thead>
              <tr className="bg-slate-900 text-white uppercase text-[8px] tracking-widest font-black">
                <th className="px-4 py-5 border-r border-slate-800">Business Unit</th>
                <th className="px-4 py-5 border-r border-slate-800 text-center">Participation %</th>
                <th className="px-4 py-5 border-r border-slate-800 text-center">Volume (S/T)</th>
                <th className="px-4 py-5 border-r border-slate-800 text-center text-emerald-400">Acc. Idea</th>
                <th className="px-4 py-5 border-r border-slate-800 text-center text-emerald-400">Acc. Imp.</th>
                <th className="px-4 py-5 border-r border-slate-800 text-center text-red-400">Rej. Idea</th>
                <th className="px-4 py-5 border-r border-slate-800 text-center text-red-400">Rej. Imp.</th>
                <th className="px-4 py-5 border-r border-slate-800 text-center text-amber-400">Pending</th>
                <th className="px-4 py-5 text-right">Value (PKR)</th>
              </tr>
            </thead>
            <tbody className="text-[10px] divide-y divide-slate-100">
              {analytics.map(row => (
                <tr key={row.dept} className="hover:bg-slate-50 transition-colors">
