import Login from './components/Login';
import Dashboard from './components/Dashboard';
import KaizenForm from './components/KaizenForm';
import Records from './components/Records';
import AdminGlobalAnalytics from './components/AdminGlobalAnalytics';

/** 
 * CLOUD CONFIGURATION 
 * Replace these with your actual keys from Supabase Settings -> API
 */
const SUPABASE_URL = (process.env as any).SUPABASE_URL || 'YOUR_SUPABASE_URL_HERE';
const SUPABASE_KEY = (process.env as any).SUPABASE_KEY || 'YOUR_SUPABASE_ANON_KEY_HERE';

const supabase = createClient(SUPABASE_URL, SUPABASE_KEY);

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [kaizens, setKaizens] = useState<Kaizen[]>([]);
  const [activeTab, setActiveTab] = useState<'dashboard' | 'submit' | 'records' | 'analytics'>('dashboard');
  const [isSyncing, setIsSyncing] = useState(false);

  // FETCH DATA FROM CLOUD
  const fetchCloudData = async () => {
    setIsSyncing(true);
    try {
      const { data, error } = await supabase
        .from('kaizens')
        .select('*')
        .order('created_at', { ascending: false });

      if (error) throw error;
      if (data) setKaizens(data as Kaizen[]);
    } catch (e) {
      console.error("Cloud fetch failed:", e);
    } finally {
      setIsSyncing(false);
    }
  };

  useEffect(() => {
    fetchCloudData();
    // Auto-refresh every 60 seconds to keep devices synced
    const interval = setInterval(fetchCloudData, 60000);
    return () => clearInterval(interval);
  }, []);

  // ADD TO CLOUD
  const addKaizen = async (newKaizen: Kaizen) => {
    setIsSyncing(true);
    try {
      // Optimistic update (UI feels fast)
      setKaizens(prev => [newKaizen, ...prev]);

      const { error } = await supabase.from('kaizens').insert([newKaizen]);
      if (error) throw error;

      // Navigate to records after successful save
      setTimeout(() => setActiveTab('records'), 300);
