      // Re-fetch to fix UI state
      fetchCloudData();
    } finally {
      setIsSyncing(false);
    }
  };

  // UPDATE IN CLOUD
  const updateKaizen = async (updatedKaizen: Kaizen) => {
    setIsSyncing(true);
    try {
      setKaizens(prev => prev.map(k => k.id === updatedKaizen.id ? updatedKaizen : k));
      const { error } = await supabase
        .from('kaizens')
        .update(updatedKaizen)
        .eq('id', updatedKaizen.id);
      if (error) throw error;
    } catch (e) {
      alert("Error updating. Cloud sync failed.");
      fetchCloudData();
    } finally {
      setIsSyncing(false);
    }
  };

  const handleLogin = (user: User) => {
    setCurrentUser(user);
    setActiveTab('dashboard');
